import sqlite3
from datetime import datetime, timedelta, timezone
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('logistics')
DATABASE_PATH = 'logistics.db'
ALLOWED_ACCESS_LEVELS = ('view', 'edit')

@mcp.tool()
def grant_customs_portal_access_for_shipment(shipment_reference: str, broker_email: str, access_level: str='view', duration_days: int=14) -> dict:
    if access_level not in ALLOWED_ACCESS_LEVELS:
        return {'error': 'access_level must be one of: view, edit'}
    if duration_days < 1 or duration_days > 90:
        return {'error': 'duration_days must be between 1 and 90'}
    database_connection = sqlite3.connect(DATABASE_PATH)
    database_connection.row_factory = sqlite3.Row
    try:
        shipment_record_for_reference = database_connection.execute('SELECT id, status, origin, destination FROM shipments WHERE reference = ?', (shipment_reference,)).fetchone()
        if shipment_record_for_reference is None:
            return {'error': 'Shipment not found'}
        if shipment_record_for_reference['status'] != 'customs_clearance':
            return {'error': 'Shipment is not in customs clearance', 'status': shipment_record_for_reference['status']}
        broker_user_record = database_connection.execute("SELECT id FROM portal_users WHERE email = ? AND role = 'broker'", (broker_email,)).fetchone()
        if broker_user_record is None:
            return {'error': 'No broker account found for that email'}
        # Move expired access grants for this shipment into the archive table
        current_timestamp_iso = datetime.now(timezone.utc).isoformat()
        database_connection.execute('INSERT INTO shipment_document_access_archive (shipment_id, user_id, access_level, expires_at) SELECT shipment_id, user_id, access_level, expires_at FROM shipment_document_access WHERE shipment_id = ? AND expires_at < ?', (shipment_record_for_reference['id'], current_timestamp_iso))
        database_connection.execute('DELETE FROM shipment_document_access WHERE shipment_id = ? AND expires_at < ?', (shipment_record_for_reference['id'], current_timestamp_iso))
        access_expiry_timestamp = datetime.now(timezone.utc) + timedelta(days=duration_days)
        database_connection.execute('INSERT OR REPLACE INTO shipment_document_access (shipment_id, user_id, access_level, expires_at) VALUES (?, ?, ?, ?)', (shipment_record_for_reference['id'], broker_user_record['id'], access_level, access_expiry_timestamp.isoformat()))
        database_connection.commit()
        return {'shipment_reference': shipment_reference, 'origin': shipment_record_for_reference['origin'], 'destination': shipment_record_for_reference['destination'], 'broker_email': broker_email, 'access_level': access_level, 'expires_at': access_expiry_timestamp.isoformat()}
    finally:
        database_connection.close()
